// Imagem candidata: transação SEMPRE revertida. WhatsApp, Graph e HTTP de
// projetos simulados. O gateway de escopo de projetos permanece real.
const assert=require('node:assert/strict');
const {PrismaClient}=require('@prisma/client');
const {Logger}=require('@nestjs/common');
const {CadastroWhatsappService}=require('./dist/modules/cadastro-whatsapp/cadastro-whatsapp.module');
const {WhatsappInicioService}=require('./dist/modules/cadastro-whatsapp/whatsapp-inicio.service');
const {WhatsappInboundService}=require('./dist/modules/agenda/whatsapp-inbound.module');
const {WhatsappGuiadoService}=require('./dist/modules/agenda/whatsapp-guiado.service');
const {WhatsappEquipeService}=require('./dist/modules/agenda/whatsapp-equipe.service');
const {WhatsappContextoService}=require('./dist/modules/agenda/whatsapp-contexto.service');
const {AuthService}=require('./dist/modules/auth/auth.service');
Logger.overrideLogger(false);
const db=new PrismaClient(),phone='5511999990001',lid='990000000000001@lid';
const marker='guia-'+Date.now(),email=marker+'@example.invalid',emailFinal=marker+'-corrigido@example.invalid';
const rollback=new Error('ROLLBACK_AURELIA_GUIADA');
let checks=0;const check=(v,msg)=>{assert.ok(v,msg);checks++;};
(async()=>{
 const before=await db.user.findMany({select:{id:true,trialExpiraEm:true,assinaturaEm:true,assinaturaValidaAte:true},orderBy:{id:'asc'}});
 try{
  await db.$transaction(async transaction=>{
   await transaction.$executeRawUnsafe("SET LOCAL lock_timeout='3s'");
   const tx=new Proxy(transaction,{get(target,key){if(key==='$transaction')return async fn=>fn(tx);const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});
   check(!await tx.userProfile.findFirst({where:{whatsapp:phone}}),'fixture phone already exists');
   check(!await tx.user.findFirst({where:{cpf:'52998224725'}}),'fixture CPF already exists');
   const messages=[];const wa={sendMessage:async(...a)=>{messages.push(a);return true;},sendToJid:async(...a)=>{messages.push(a);return true;}};
   const inicio=new WhatsappInicioService(tx,wa);inicio.entregar=async()=>{};
   const cadastro=new CadastroWhatsappService(tx,wa,inicio);
   let perms=['*'];const auth={resolvePermissions:async()=>perms};
   const wb={onEventCreated:async()=>{},onEventUpdated:async()=>{},onEventDeleted:async()=>{}};
   const equipe=new WhatsappEquipeService(tx,wa,auth);
   let projectCalls=0;
   equipe.chamar=async(u,path,method,data)=>{
     projectCalls++;
     if(path===''&&method==='POST')return tx.project.create({data:{organizationId:u.organizationId,criadoPorId:u.id,...data}});
     const create=path.match(/^\/([^/]+)\/tasks$/);
     if(create&&method==='POST')return tx.task.create({data:{projectId:create[1],criadoPorId:u.id,...data}});
     const status=path.match(/^\/([^/]+)\/tasks\/([^/]+)\/status$/);
     if(status&&method==='PATCH')return tx.task.update({where:{id:status[2]},data});
     throw new Error('Unexpected simulated project request');
   };
   const guia=new WhatsappGuiadoService(tx,wa,auth,equipe,wb);
   const contexto=new WhatsappContextoService(tx);
   const inbound=new WhatsappInboundService(tx,wa,auth,{},cadastro,inicio,{tratar:async()=>{}},contexto,equipe,{tratar:async()=>({})},{tratar:async()=>({})},undefined,guia);
   let messageId=0;
   const send=text=>inbound.processarMensagem({instance:'probe-guia',data:{key:{id:'probe-'+(++messageId),remoteJid:lid,remoteJidAlt:phone+'@s.whatsapp.net',fromMe:false},message:{conversation:text}}});
   const last=()=>messages.at(-1)?.[1]||'';
   const form=()=>cadastro.conversaAberta(phone,lid);
   await send('Oi');check((await form()).etapa==='INICIO','spontaneous contact not guided');check(last().includes('Criar minha conta gratuita'),'registration choices missing');
   await send('3');check(last().includes('compromissos'),'learn-more path missing');
   await send('1');check((await form()).etapa==='NOME','option 1 did not start name');
   await send('Pessoa Verificação');await send('123');check((await form()).etapa==='CPF','bad CPF lost registration');
   await send('voltar');check((await form()).nome==='Pessoa Verificação','back erased name');await send('manter');
   await send('52998224725');await send(email);await send('1');check((await form()).etapa==='CONFIRMACAO','personal choice failed');
   await send('2');await send('3');await send(emailFinal);check((await form()).etapa==='CONFIRMACAO','single-field correction failed');
   check((await form()).nome==='Pessoa Verificação','correction lost name');
   await send('Confirmo meus dados.');const user=await tx.user.findFirst({where:{email:emailFinal}});check(!!user,'signup not concluded');
   check(user.trialExpiraEm===null&&user.assinaturaEm===null,'new free signup changed terms');
   const realAuth=new AuthService(tx,null,{get:()=>undefined},{get:()=>undefined,set:()=>{}},null,null,null);
   check(!await realAuth.checkGlobalSuperAdmin(user.id,emailFinal),'new account granted global SA');
   const guiastate=async()=>(await tx.$queryRaw`SELECT dados FROM whatsapp_inicio WHERE user_id=${user.id} AND instancia='probe-guia' AND conversa=${lid}`)[0]?.dados;
   await send('menu');check(last().includes('Anotações')&&!last().includes('Keep'),'simple main menu missing');
   for(const t of ['2','1','Comprar pilhas'])await send(t);
   check(await tx.note.count({where:{userId:user.id}})===0,'note saved before confirmation');
   await send('1');check(await tx.note.count({where:{userId:user.id}})===1,'note not saved');
   for(const t of ['2','2','1','1'])await send(t);
   await send('voltar');check((await guiastate()).fase==='ITEM','back did not restore action menu');
   for(const t of ['1','1'])await send(t);await send('voltar');check((await guiastate()).fase==='CORRIGIR','back did not restore field menu');
   for(const t of ['1','Comprar pilhas e pão','1'])await send(t);
   check((await tx.note.findFirst({where:{userId:user.id}})).conteudo==='Comprar pilhas e pão','note correction failed');
   for(const t of ['menu','3','1','Mercado','abc'])await send(t);
   check((await guiastate()).v.descricao==='Mercado','invalid amount lost description');
   for(const t of ['48,90','1','hoje'])await send(t);
   check(await tx.gasto.count({where:{userId:user.id}})===0,'expense saved before confirmation');
   for(const t of ['2','2','55,90'])await send(t);
   check(last().includes('Mercado')&&last().includes('55,90'),'expense correction lost fields');
   await send('1');check(Number((await tx.gasto.findFirst({where:{userId:user.id}})).valor)===55.9,'expense wrong amount');
   for(const t of ['menu','1','1','Dentista','31/02/2027 14h'])await send(t);
   check((await guiastate()).fase==='FORM','invalid appointment date accepted');
   for(const t of ['amanhã às 14h','60','1'])await send(t);
   check(await tx.event.count({where:{userId:user.id}})===0,'appointment saved before confirmation');
   await send('1');const event=await tx.event.findFirst({where:{userId:user.id}});check(event.fim-event.inicio===3600000,'appointment duration changed');
   for(const t of ['menu','5','1','Comprar remédio','amanhã','1'])await send(t);
   check(await tx.dailyTask.count({where:{userId:user.id}})===1,'personal task not created');
   for(const t of ['menu','5','2','1','2','1'])await send(t);
   check((await tx.dailyTask.findFirst({where:{userId:user.id}})).concluido,'personal task not concluded');
   for(const t of ['menu','4','1','Reforma da casa','pular','pular'])await send(t);
   check(projectCalls===0,'project created before confirmation');await send('1');
   check(await tx.project.count({where:{organizationId:user.organizationId}})===1,'project not created');
   for(const t of ['menu','4','2','1','2','Pintar sala','pular','amanhã'])await send(t);
   check(last().includes('Pessoa Verificação')&&!last().includes('U-'),'assignee names not shown');
   await send('1');check(projectCalls===1,'task created before confirmation');await send('1');
   const task=await tx.task.findFirst({where:{project:{organizationId:user.organizationId}}});check(task.assigneeId===user.id,'task assignee not selected');
   for(const t of ['menu','4','2','1','1','1','3'])await send(t);
   check(last().includes('Pintar sala')&&last().includes('Concluída'),'task status preview missing target');await send('1');
   check((await tx.task.findUnique({where:{id:task.id}})).status==='CONCLUIDA','project task not concluded');
   for(let i=0;i<6;i++)await tx.note.create({data:{organizationId:user.organizationId,userId:user.id,titulo:'Página '+i,conteudo:'Conteúdo'}});
   for(const t of ['menu','2','2'])await send(t);check(last().includes('Próxima página'),'pagination not offered');await send('8');check((await guiastate()).v.pagina===1,'next page failed');
   for(const t of ['menu','2','1','Nota sem permissão'])await send(t);const count=await tx.note.count({where:{userId:user.id}});perms=['keep:ver'];await send('1');check(await tx.note.count({where:{userId:user.id}})===count,'revoked permission still wrote');perms=['*'];
   const org2=await tx.organization.create({data:{nome:'Outra empresa',slug:marker+'-outra'}});
   const other=await tx.user.create({data:{nome:'Outra Pessoa',organizationId:org2.id,email:marker+'-other@example.invalid',senhaHash:'inutilizavel'}});
   await tx.note.create({data:{organizationId:org2.id,userId:other.id,titulo:'NAO_EXIBIR_OUTRA_EMPRESA',conteudo:'Privado'}});
   for(const t of ['menu','2','2'])await send(t);check(!last().includes('NAO_EXIBIR'),'other organization data exposed');
   let refused=false;try{await equipe.executarGuiado(other,'demanda.status',{projectId:task.projectId,taskId:task.id,status:'A_FAZER'});}catch{refused=true;}check(refused,'foreign project accepted');
   for(const t of ['menu','2','1','Não salvar','cancelar'])await send(t);check(await tx.note.count({where:{userId:user.id,conteudo:'Não salvar'}})===0,'cancel saved note');
   for(const t of ['menu','6','6'])await send(t);check(last().includes('opções avançadas')&&last().includes('/login'),'site boundaries not explained');
   await send('0');check(!await guiastate(),'exit did not close dialogue');
   throw rollback;
  },{timeout:90000});
  throw new Error('unexpected commit');
 }catch(error){if(error.message!==rollback.message)throw error;}
 check(await db.user.count({where:{email:{in:[email,emailFinal,marker+'-other@example.invalid']}}})===0,'probe users persisted');
 check(await db.userProfile.count({where:{whatsapp:phone}})===0,'probe profile persisted');
 const after=await db.user.findMany({where:{id:{in:before.map(u=>u.id)}},select:{id:true,trialExpiraEm:true,assinaturaEm:true,assinaturaValidaAte:true},orderBy:{id:'asc'}});
 check(JSON.stringify(before)===JSON.stringify(after),'existing terms changed');
 console.log(JSON.stringify({checks,database:'passed',rollback:'confirmed',real_messages_sent:0,external_project_requests:0,existing_accounts:'unchanged'}));
})().catch(error=>{console.error(error.message);process.exitCode=1;}).finally(()=>db.$disconnect());
